"""Metric layer (R5, R7).

* token level: one anomaly score per test word unit, AUROC/AUPRC computed over the
  pooled ranking of all test tokens of all test documents (micro), which is how
  Demo.ipynb computes it (`roc_auc_score(z_test, score)` on flattened token lists).
* document level: arithmetic mean of a document's token scores (Eq. 3) and
  AUROC/AUPRC over documents.
"""
import numpy as np
from sklearn.metrics import average_precision_score, roc_auc_score


def _flat(list_of_arrays):
    if len(list_of_arrays) == 0:
        return np.zeros(0)
    return np.concatenate([np.asarray(a).ravel() for a in list_of_arrays])


def token_level_metrics(token_scores, token_labels):
    scores = _flat(token_scores)
    labels = _flat(token_labels).astype(int)
    if labels.sum() == 0 or labels.sum() == len(labels):
        return {"token_auroc": float("nan"), "token_auprc": float("nan"),
                "n_tokens": int(len(labels)), "n_positive_tokens": int(labels.sum())}
    return {
        "token_auroc": float(roc_auc_score(labels, scores)),
        "token_auprc": float(average_precision_score(labels, scores)),
        "n_tokens": int(len(labels)),
        "n_positive_tokens": int(labels.sum()),
        "positive_token_rate": float(labels.mean()),
    }


def document_level_metrics(token_scores, doc_labels):
    doc_scores = np.array([float(np.mean(s)) for s in token_scores], dtype=np.float64)
    labels = np.asarray(doc_labels, dtype=int)
    out = {
        "doc_auroc": float(roc_auc_score(labels, doc_scores)),
        "doc_auprc": float(average_precision_score(labels, doc_scores)),
        "n_test_docs": int(len(labels)),
        "n_anomalous_test_docs": int(labels.sum()),
    }
    return out, doc_scores


def metric_parity_check(seed=0):
    """Validate the AUROC/AUPRC plumbing on synthetic data against sklearn."""
    rng = np.random.default_rng(seed)
    y = rng.integers(0, 2, size=500)
    s = rng.normal(size=500) + y * 0.5
    tok = token_level_metrics([s[:250], s[250:]], [y[:250], y[250:]])
    ref_auroc = roc_auc_score(y, s)
    ref_auprc = average_precision_score(y, s)
    return {
        "auroc": tok["token_auroc"], "auroc_sklearn": float(ref_auroc),
        "auprc": tok["token_auprc"], "auprc_sklearn": float(ref_auprc),
        "max_abs_diff": float(max(abs(tok["token_auroc"] - ref_auroc), abs(tok["token_auprc"] - ref_auprc))),
    }

